def _handle_dict(target, spec, scope):
    if not isinstance(target, dict):
        raise TypeMatchError(type(target), dict)
    spec_keys = list(spec.keys())

    matched_keys = set()
    result = {}

    sorted_spec_keys = sorted(spec_keys, key=_precedence)

    for target_key, target_val in target.items():
        matched = False
        for spec_key in sorted_spec_keys:
            actual_key = spec_key
            if type(spec_key) in (Required, Optional):
                actual_key = spec_key.key
            try:
                matched_key_val = scope[glom](target_key, actual_key, scope)
                result[matched_key_val] = scope[glom](target_val, spec[spec_key], scope)
                matched_keys.add(spec_key)
                matched = True
                break
            except GlomError:
                pass
        if not matched:
            raise MatchError("key {0!r} didn't match any of {1!r}", target_key, sorted_spec_keys)

    for spec_key in spec_keys:
        if type(spec_key) is Required:
            if spec_key not in matched_keys:
                raise MatchError("target missing expected keys {0!r}", spec_key)
        elif type(spec_key) is Optional:
            if spec_key not in matched_keys:
                if spec_key.default is not _MISSING:
                    result[spec_key.key] = spec_key.default
        elif _precedence(spec_key) == 0:
            if spec_key not in matched_keys:
                raise MatchError("target missing expected keys {0!r}", spec_key)

    return result
```

